template.script:
window.currentSlide = 1;
window.nextSlide = function() {
    const slides = document.querySelectorAll('.certificate_document');
    if (window.currentSlide < slides.length) window.currentSlide++;
    window.showSlide();
};
window.prevSlide = function() {
    if (window.currentSlide > 1) window.currentSlide--;
    window.showSlide();
};
window.showSlide = function() {
    document.querySelectorAll('.certificate_document').forEach((slide, index) => {
        slide.style.display = index + 1 === window.currentSlide ? 'block' : 'none';
    });
};
window.showSlide();
